import zipfile, re, xml.etree.ElementTree as ET, io
from pathlib import Path
from collections import defaultdict
from decimal import Decimal
from datetime import datetime, timedelta

p = Path.home() / "Downloads" / "极乐引擎_明细数据_2026.11.02_1.xlsx"
z = zipfile.ZipFile(p)
ns = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
ss = ["".join(t.text or "" for t in si.findall(".//m:t", ns)) for si in ET.fromstring(z.read("xl/sharedStrings.xml")).findall("m:si", ns)]

def col_to_idx(col):
    n = 0
    for c in col:
        n = n * 26 + (ord(c) - 64)
    return n - 1

def cell_value(c):
    t = c.attrib.get("t")
    v = c.find("m:v", ns)
    if v is None or v.text is None:
        return ""
    return ss[int(v.text)] if t == "s" else v.text

def num(x):
    x = str(x).strip().replace(",", "")
    return Decimal(x) if x else Decimal(0)

def norm_date(t):
    t = str(t).strip()
    for fmt in ("%Y/%m/%d", "%Y-%m-%d"):
        try:
            return datetime.strptime(t, fmt).date().isoformat()
        except Exception:
            pass
    try:
        return (datetime(1899, 12, 30) + timedelta(days=float(t))).date().isoformat()
    except Exception:
        return t

want = ["渠道码", "产品ID", "时间", "VIP充值-原始", "金币充值", "新增-原始"]
want_idx = {}
cells = {}
rows = 0
by_day = defaultdict(lambda: defaultdict(Decimal))
for event, elem in ET.iterparse(io.BytesIO(z.read("xl/worksheets/sheet1.xml")), events=("end",)):
    if elem.tag.endswith("}c"):
        m = re.match(r"([A-Z]+)", elem.attrib.get("r", ""))
        if m:
            cells[col_to_idx(m.group(1))] = cell_value(elem)
        elem.clear()
    elif elem.tag.endswith("}row"):
        rows += 1
        if rows == 1:
            maxc = max(cells)
            headers = [cells.get(i, "") for i in range(maxc + 1)]
            for i, h in enumerate(headers):
                if h in want:
                    want_idx[h] = i
        else:
            def g(n):
                i = want_idx.get(n)
                return cells.get(i, "") if i is not None else ""
            if str(g("产品ID")).strip() == "YC-169" and str(g("渠道码")).strip() == "yVvLuXos":
                d = norm_date(g("时间"))
                by_day[d]["vip"] += num(g("VIP充值-原始"))
                by_day[d]["coin"] += num(g("金币充值"))
                by_day[d]["new"] += num(g("新增-原始"))
        cells = {}
        elem.clear()

focus = ["2026-10-03", "2026-10-18", "2026-10-26", "2026-10-28", "2026-10-31"]
print("xlsx focus days:")
for d in focus:
    v = by_day[d]
    print(d, "vip", v["vip"], "coin", v["coin"], "rev", v["vip"] + v["coin"], "new", v["new"])
print(
    "xlsx month rev",
    sum(v["vip"] + v["coin"] for v in by_day.values()),
    "new",
    sum(v["new"] for v in by_day.values()),
)
